const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const laJolla = ee.Geometry.Point([-117.274, 32.847]); // La Jolla, CA coordinates
    const date = '2018-08-01';
    const bufferDistance = 1000; // 1km buffer to ensure we get water pixels

    // Create a buffer around the point to get nearby ocean pixels
    const region = laJolla.buffer(bufferDistance);

    // 2. Data Acquisition - Try multiple SST datasets
    let sstImage = null;
    let datasetUsed = '';

    // Function to get MODIS SST image with quality masking
    const getMODIS_SST = function(collectionId, date) {
        const col = ee.ImageCollection(collectionId)
            .filterDate(date, ee.Date(date).advance(1, 'day'))
            .filterBounds(region);

        if (col.size().getInfo() === 0) return null;

        const img = col.first();
        // MODIS SST is in Kelvin, convert to Celsius
        const sst = img.select('sst').multiply(0.01).subtract(273.15); // Scale factor 0.01 for MODIS

        // Use quality flag (0=bad, 3=best)
        const quality = img.select('qual_sst');
        const mask = quality.gte(2); // Keep medium and high quality

        return sst.updateMask(mask);
    };

    // Try MODIS Terra (MOD28) first
    sstImage = getMODIS_SST('MODIS/006/MOD28', date);
    if (sstImage) {
        datasetUsed = 'MODIS Terra (MOD28)';
    } else {
        // Try MODIS Aqua (MYD28)
        sstImage = getMODIS_SST('MODIS/006/MYD28', date);
        if (sstImage) {
            datasetUsed = 'MODIS Aqua (MYD28)';
        } else {
            // Try NOAA OISST as fallback
            const oisstCol = ee.ImageCollection('NOAA/CDR/OISST/V2_1')
                .filterDate(date, ee.Date(date).advance(1, 'day'))
                .filterBounds(region);

            if (oisstCol.size().getInfo() > 0) {
                sstImage = oisstCol.first().select('sst');
                datasetUsed = 'NOAA OISST';
            }
        }
    }

    // Check if we found any data
    if (!sstImage) {
        console.log(`No SST data found for ${date}`);
        console.log('<answer>C1</answer>');
        return;
    }

    console.log(`Dataset used: ${datasetUsed}`);

    // 3. Processing - Get SST value
    const stats = sstImage.reduceRegion({
        reducer: ee.Reducer.mean().combine({
            reducer2: ee.Reducer.count(),
            sharedInputs: true
        }),
        geometry: region,
        scale: 1000,
        maxPixels: 1e9
    });

    const meanSST = stats.get('sst_mean');
    const pixelCount = stats.get('sst_count');

    // Get values
    const meanVal = meanSST.getInfo();
    const countVal = pixelCount.getInfo();

    console.log(`Date: ${date}`);
    console.log(`Valid pixels: ${countVal}`);
    console.log(`Mean SST: ${meanVal !== null ? meanVal.toFixed(2) + '°C' : 'null'}`);

    // 4. Check for valid pixels
    if (countVal === 0 || meanVal === null) {
        console.log('No valid SST pixels after quality masking');
        console.log('<answer>C2</answer>');
        return;
    }

    // 5. Validation & Final Answer
    // Check if value is within reasonable SST range (-2 to 40°C)
    if (meanVal < -2 || meanVal > 40 || !isFinite(meanVal)) {
        console.log(`Invalid SST value: ${meanVal}°C`);
        console.log('<answer>C3</answer>');
        return;
    }

    // Check if temperature exceeded 23°C
    if (meanVal > 23) {
        console.log(`SST (${meanVal.toFixed(2)}°C) exceeded 23°C`);
        console.log('<answer>A</answer>');
    } else {
        console.log(`SST (${meanVal.toFixed(2)}°C) did not exceed 23°C`);
        console.log('<answer>B</answer>');
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE();
